using System.Buffers;
using McProtoNet.NBT;
using McProtoNet.Protocol;
using McProtoNet.Primitives;
using ConfigCb = McProtoNet.Protocol.Packets.Configuration.Clientbound;
using ConfigSb = McProtoNet.Protocol.Packets.Configuration.Serverbound;
using LoginSb = McProtoNet.Protocol.Packets.Login.Serverbound;
using PlaySb = McProtoNet.Protocol.Packets.Play.Serverbound;

namespace McProtoNet.Tests.Protocol;

/// <summary>
/// Round-trip tests for the C# sources generated by minecraft-protocol-fs and delivered into
/// src/McProtoNet.Protocol/Generated. Exercises the real McProtoNet.Primitives API end to end:
/// write a generated packet, read it back, and check the result matches (plus GetPacketId against
/// the fs packet-id manifest, Spec/protocol-ids.json).
/// </summary>
public class GeneratedRoundTripTests
{
    private static T RoundTrip<T>(T value, int pv) where T : IProtocolType<T>
    {
        var writer = new MinecraftPrimitiveWriter();
        value.Write(writer, pv);
        using var mem = writer.GetWrittenMemory();
        var reader = new MinecraftPrimitiveReader(new ReadOnlySequence<byte>(mem.Memory));
        return T.Read(ref reader, pv);
    }

    // ── Configuration KeepAlive ───────────────────────────────────────────────

    [Theory]
    [InlineData(764)]
    [InlineData(772)]
    public void ConfigurationKeepAlive_Clientbound_RoundTrips(int pv)
    {
        var p = new ConfigCb.KeepAlivePacket(123456789L);
        var back = RoundTrip(p, pv);
        Assert.Equal(p, back);
    }

    [Theory]
    [InlineData(764)]
    [InlineData(772)]
    public void ConfigurationKeepAlive_Serverbound_RoundTrips(int pv)
    {
        var p = new ConfigSb.KeepAlivePacket(-987654321L);
        var back = RoundTrip(p, pv);
        Assert.Equal(p, back);
    }

