    // ── Configuration SelectKnownPacks ────────────────────────────────────────
    // KnownPack[] / KnownPack are plain classes with no value equality, so compare field by field.

    private static void AssertPacksEqual(KnownPack[] expected, KnownPack[] actual)
    {
        Assert.Equal(expected.Length, actual.Length);
        for (int i = 0; i < expected.Length; i++)
        {
            Assert.Equal(expected[i].Namespace, actual[i].Namespace);
            Assert.Equal(expected[i].Id, actual[i].Id);
            Assert.Equal(expected[i].Version, actual[i].Version);
        }
    }

    [Theory]
    [InlineData(766)]
    [InlineData(772)]
    public void SelectKnownPacks_Clientbound_TwoPacks_RoundTrips(int pv)
    {
        var packs = new[]
        {
            new KnownPack("minecraft", "core", "1.21"),
            new KnownPack("minecraft", "chat_type", "1.21"),
        };
        var p = new ConfigCb.SelectKnownPacksPacket(packs);
        var back = RoundTrip(p, pv);
        AssertPacksEqual(packs, back.Packs);
    }

    [Theory]
    [InlineData(766)]
    [InlineData(772)]
    public void SelectKnownPacks_Clientbound_EmptyArray_RoundTrips(int pv)
    {
        var p = new ConfigCb.SelectKnownPacksPacket([]);
        var back = RoundTrip(p, pv);
        Assert.Empty(back.Packs);
    }

    [Theory]
    [InlineData(766)]
    [InlineData(772)]
    public void SelectKnownPacks_Serverbound_TwoPacks_RoundTrips(int pv)
    {
        var packs = new[]
        {
            new KnownPack("minecraft", "core", "1.21"),
            new KnownPack("minecraft", "chat_type", "1.21"),
