    // ── Configuration Disconnect ───────────────────────────────────────────────

    [Fact]
    public void Disconnect_764_StringReason_RoundTrips()
    {
        var p = new ConfigCb.DisconnectPacket(V764: new("{\"text\":\"kicked\"}"));
        var back = RoundTrip(p, 764);
        Assert.Equal(p.V764?.ReasonJson, back.V764?.ReasonJson);
    }

    // Was skipped until 2026-08-13: the codegen's primitive table had the root-name flag inverted,
    // so an anonymousNbt field was read with a name and written without one. Fixed in
    // minecraft-protocol-fs (CSharpSurface.Primitives) and re-delivered; both sides now agree on
    // the nameless network root.
    [Fact]
    public void Disconnect_772_NbtReason_RoundTrips()
    {
        var reason = new NbtCompound("") { new NbtString("text", "Bye") };
        var p = new ConfigCb.DisconnectPacket(V765_Last: new(reason));
        var back = RoundTrip(p, 772);

        var backCompound = Assert.IsType<NbtCompound>(back.V765_Last?.Reason);
        Assert.Equal("Bye", backCompound.Get<NbtString>("text")!.Value);
    }

    // ── Login LoginStart: the artifact's showcase packet, four layers ─────────

    [Fact]
    public void LoginStart_758_CommonOnly_RoundTrips()
    {
        var p = new LoginSb.LoginStartPacket("TitleBot");
        var back = RoundTrip(p, 758);
        Assert.Equal("TitleBot", back.Username);
        Assert.Null(back.V764_Last);
    }

    [Fact]
    public void LoginStart_772_V764Layer_RoundTrips()
    {
        var uuid = Guid.NewGuid();
        var p = new LoginSb.LoginStartPacket("TitleBot", V764_Last: new(uuid));
        var back = RoundTrip(p, 772);

        Assert.Equal("TitleBot", back.Username);
        Assert.Equal(uuid, back.V764_Last?.PlayerUuid);
    }

    [Fact]
    public void LoginStart_772_WithoutLayer_ThrowsWrongLayer()
    {
        var p = new LoginSb.LoginStartPacket("TitleBot");
        var writer = new MinecraftPrimitiveWriter();

        Assert.Throws<WrongLayerException>(() => p.Write(writer, 772));
    }

    // ── FixedBytes: exactly-n bytes, no length prefix ────────────────────────

    private static PlaySb.ChatCommandSignedPacket ChatCommandSigned(byte[] acknowledged, int pv)
        => new(
            "gamemode creative",
            1_700_000_000_000L,
            -42L,
            [new ArgumentSignature("target", [.. Enumerable.Range(0, 256).Select(i => (byte)i)])],
            3,
            acknowledged,
            pv >= 770 ? new PlaySb.ChatCommandSignedPacket.V770_LastLayer(9) : null);

    [Theory]
    [InlineData(768)]
    [InlineData(772)]
    public void ChatCommandSigned_FixedBytes_RoundTrips(int pv)
    {
        var p = ChatCommandSigned([0xAA, 0xBB, 0xCC], pv);
        var back = RoundTrip(p, pv);

        Assert.Equal(p.Command, back.Command);
        Assert.Equal(p.Timestamp, back.Timestamp);
        Assert.Equal(p.Salt, back.Salt);
        Assert.Equal(p.MessageCount, back.MessageCount);
        Assert.Equal(p.Acknowledged, back.Acknowledged);
        Assert.Equal(p.V770_Last, back.V770_Last);
        Assert.Equal(256, back.ArgumentSignatures[0].Signature.Length);
        Assert.Equal(p.ArgumentSignatures[0].Signature, back.ArgumentSignatures[0].Signature);
    }

    [Theory]
    [InlineData(2)]
    [InlineData(4)]
    public void ChatCommandSigned_WrongFixedLength_Throws(int length)
    {
        var p = ChatCommandSigned(new byte[length], 772);

        Assert.Throws<ArgumentException>(() => p.Write(new MinecraftPrimitiveWriter(), 772));
    }

    [Fact]
    public void ChatCommandSigned_FixedBytes_ConsumesExactlyThreeBytes()
    {
        var p = ChatCommandSigned([1, 2, 3], 768);
        var writer = new MinecraftPrimitiveWriter();
        p.Write(writer, 768);
        using var mem = writer.GetWrittenMemory();

        // command + timestamp + salt + one signature + count + 3 acknowledged bytes, nothing else
        var expected = 1 + "gamemode creative".Length + 8 + 8
                       + 1 + 1 + "target".Length + 256
                       + 1 + 3;
        Assert.Equal(expected, mem.Memory.Length);
    }

    // ── GetPacketId vs the fs packet-id manifest (Spec/protocol-ids.json) ─────

    [Fact]
    public void GetPacketId_MatchesManifest()
    {
        Assert.Equal(0x01, ConfigCb.DisconnectPacket.GetPacketId(764));
        Assert.Equal(0x02, ConfigCb.DisconnectPacket.GetPacketId(772));

        Assert.Equal(0x02, ConfigCb.FinishConfigurationPacket.GetPacketId(764));
        Assert.Equal(0x02, ConfigSb.FinishConfigurationPacket.GetPacketId(764));
        Assert.Equal(0x03, ConfigSb.FinishConfigurationPacket.GetPacketId(766));

        Assert.Equal(0x03, ConfigCb.KeepAlivePacket.GetPacketId(764));
        Assert.Equal(0x04, ConfigCb.KeepAlivePacket.GetPacketId(772));
        Assert.Equal(0x03, ConfigSb.KeepAlivePacket.GetPacketId(764));
        Assert.Equal(0x04, ConfigSb.KeepAlivePacket.GetPacketId(772));

        Assert.Equal(0x0E, ConfigCb.SelectKnownPacksPacket.GetPacketId(766));
        Assert.Equal(0x0E, ConfigCb.SelectKnownPacksPacket.GetPacketId(772));
        Assert.Equal(0x07, ConfigSb.SelectKnownPacksPacket.GetPacketId(766));
        Assert.Equal(0x07, ConfigSb.SelectKnownPacksPacket.GetPacketId(772));

        Assert.Equal(0x00, ConfigSb.ClientInformationPacket.GetPacketId(766));
        Assert.Equal(0x00, ConfigSb.ClientInformationPacket.GetPacketId(772));

        Assert.Equal(0x10, PlaySb.KeepAlivePacket.GetPacketId(735));
        Assert.Equal(0x1B, PlaySb.KeepAlivePacket.GetPacketId(772));
    }
}
